 var target=/läs|kapitel|berättelse|reader/i.test(profile.nexus+' '+profile.title)?'stories':/kunskap|graf|relation|backlink/i.test(profile.nexus+' '+profile.title)?'knowledge':/dokument|fil|arkiv|pdf/i.test(profile.nexus+' '+profile.title)?'files':'films';
