 if(profile.kind==='knowledge-links')return '<section class="dk-knowledge-links">'+N.slice(index%Math.max(1,N.length),index%Math.max(1,N.length)+4).map(function(n){return '<button data-node="'+e(n.id)+'">◇ '+e(n.id)+' · '+e(n.kind)+'</button>';}).join('')+note+'</section>';
 return note+button(ctx,'Utforska '+target,target);
